// Parsear payload de WhatsApp Cloud API
const body = $input.first().json.body;

if (!body || !body.entry || !body.entry[0]) {
  return [{ json: { skip: true, reason: 'no_entry' } }];
}

const entry = body.entry[0];
const changes = entry.changes;

if (!changes || !changes[0] || !changes[0].value) {
  return [{ json: { skip: true, reason: 'no_changes' } }];
}

const value = changes[0].value;

if (!value.messages || value.messages.length === 0) {
  return [{ json: { skip: true, reason: 'status_update_only' } }];
}

const message = value.messages[0];
const contact = value.contacts ? value.contacts[0] : {};

const result = {
  skip: false,
  message_id: message.id,
  from: message.from,
  timestamp: message.timestamp,
  type: message.type,
  contact_name: contact.profile ? contact.profile.name : '',
  text: message.type === 'text' ? message.text.body : null,
  audio_id: message.type === 'audio' ? message.audio.id : null,
  image_id: message.type === 'image' ? message.image.id : null,
  document_id: message.type === 'document' ? message.document.id : null,
  caption: message.image ? message.image.caption : (message.document ? message.document.caption : null),
  phone_number_id: value.metadata.phone_number_id,
  display_phone: value.metadata.display_phone_number
};

return [{ json: result }];

// Procesar respuesta del Router
const responseBody = $input.first().json;
let routerResponse;

try {
  routerResponse = JSON.parse(responseBody.choices[0].message.content);
} catch(e) {
  routerResponse = {
    intent: 'chat',
    department: 'ceo',
    items: [],
    confirmation_message: 'Perdon Jona, no logre procesar eso. Podrias repetirlo?',
    requires_approval: false
  };
}

const originalMessage = $node['Parse WhatsApp Message'].json;

return [{ json: {
  ...routerResponse,
  original_from: originalMessage.from,
  original_text: originalMessage.text,
  phone_number_id: originalMessage.phone_number_id
}}];
